const STYLE_T={controle:{c:5,p:2},poly:{c:4,p:3},puissance:{c:2,p:5}};
const NIV={debutant:1,inter:2,avance:3};
function recommend(a){
 const t={...STYLE_T[a.style]};
 if(a.cote==="gauche"){t.p=Math.min(5,t.p+0.5);} else if(a.cote==="droite"){t.c=Math.min(5,t.c+0.5);}
 const niv=NIV[a.niveau];
 const scored=RACKETS.map(r=>{
  let s=100;
  s-=Math.abs(r.controle-t.c)*12+Math.abs(r.puissance-t.p)*12;
  s-=Math.abs(r.niveau-niv)*14;
  if(a.genre==="femme"){ if(r.genre==="femme") s+=18; else if(parseInt(r.poids)>355) s-=10; }
  else { if(r.genre==="femme") s-=22; }
  if(a.confort==="oui"){ s+= (r.confort-3)*9; if(r.forme==="diamant") s-=12; }
  if(a.marques&&a.marques.length&&!a.marques.includes(r.marque)) return null;
  if(r.prix>a.budget){ if(r.prix<=a.budget*1.1) s-=8; else return null; }
  else { s+=Math.min(8,(a.budget-r.prix)/25); } // slight bonus for spending less, cap
  return {...r,s};
 }).filter(Boolean).sort((x,y)=>y.s-x.s);
 return scored;
}
function why(r,a){
 const w=[];
 w.push({ronde:"forme ronde, balance basse : contrôle et tolérance",goutte:"forme goutte d'eau : l'équilibre contrôle / puissance",diamant:"forme diamant, balance haute : puissance au smash"}[r.forme]);
 if(a.cote==="gauche"&&r.puissance>=4) w.push("assez de punch pour conclure côté gauche");
 if(a.cote==="droite"&&r.controle>=4) w.push("la régularité qu'il faut au joueur de droite");
 if(a.confort==="oui"&&r.confort>=4) w.push("mousse confortable, bras préservé");
 if(a.genre==="femme"&&r.genre==="femme") w.push("gamme allégée");
 if(r.niveau===NIV[a.niveau]) w.push("adaptée à ton niveau");
 if(r.prix<=a.budget*0.8) w.push("bien dans ton budget");
 return w.slice(0,4).join(" · ");
}
function bar(v,cls=""){return `<div class="bar ${cls}"><i style="width:${v*20}%"></i></div>`;}
/* Marques préférées : cases générées depuis la base (une nouvelle marque apparaît d'elle-même), filtre strict si au moins une est cochée */
const MARQUES=[...new Set(RACKETS.map(r=>r.marque))].sort((x,y)=>x.localeCompare(y,"fr"));
function marquesChoisies(){return [...document.querySelectorAll('#marques input:checked')].map(i=>i.value);}
function toutesMarques(){document.querySelectorAll('#marques input').forEach(i=>{i.checked=false;});resumeMarques();render();}
function resumeMarques(){
 const m=marquesChoisies();
 document.getElementById("marques-resume").textContent=!m.length?"Toutes les marques":m.length<=3?m.join(", "):m.length+" marques choisies";
}
(function(){
 const zone=document.getElementById("marques");
 if(!zone) return;
 MARQUES.forEach(m=>{
  const l=document.createElement("label"),i=document.createElement("input"),n=document.createElement("small");
  i.type="checkbox";i.name="marque";i.value=m;n.textContent=" "+RACKETS.filter(r=>r.marque===m).length;
  l.append(i,m,n);zone.appendChild(l);
 });
 const effacer=document.createElement("button");effacer.type="button";effacer.className="marques-effacer";effacer.textContent="Toutes les marques";
 effacer.addEventListener("click",toutesMarques);
 zone.appendChild(effacer);
 zone.addEventListener("change",resumeMarques);
})();
const NOMS_NIVEAU=["","débutant","intermédiaire","avancé"];
function render(){
 const f=document.getElementById("quiz");
 const a={cote:f.cote.value,style:f.style.value,niveau:f.niveau.value,genre:f.genre.value,confort:f.confort.value,budget:+f.budget.value,marques:marquesChoisies()};
 const list=recommend(a);
 const top=list.slice(0,3);
 const res=document.getElementById("results");
 const nomsMarques=a.marques.length<=3?a.marques.join(", "):a.marques.length+" marques";
 const parmi=a.marques.length?RACKETS.filter(r=>a.marques.includes(r.marque)).length:RACKETS.length;
 document.getElementById("res-count").textContent=list.length?`${list.length} raquettes compatibles sur ${parmi}${a.marques.length?" ("+nomsMarques+")":""}`:"";
 if(!top.length){
  res.innerHTML=a.marques.length
   ?`<div class="empty"><b>Aucune raquette ${a.marques.length===1?a.marques[0]:"de ces marques"} pour ce profil dans ce budget.</b><br>Monte le budget, ajoute une marque, ou <button type="button" class="lien-btn" id="toutes-marques">regarde toutes les marques</button>.</div>`
   :`<div class="empty"><b>Aucune raquette dans ce budget avec ce profil.</b><br>Monte le budget de quelques dizaines d'euros ou choisis « Un équilibre » : les goutte d'eau d'entrée de gamme sont très bonnes pour débuter.</div>`;
  const t=document.getElementById("toutes-marques");
  if(t)t.addEventListener("click",toutesMarques);
  return;
 }
 res.innerHTML=top.map((r,i)=>`<article class="rk">
  <div class="rank">${i+1}</div>
  <div><span class="brand-l">${r.marque}</span><h3>${r.modele}</h3></div>
  <div class="price">${r.prix} €<small>prix indicatif</small></div>
  <p class="why"><b>Pourquoi :</b> ${why(r,a)}.<br>${r.desc}</p>
  <div><div class="specs"><span>Forme <b>${r.forme}</b></span><span>Balance <b>${r.balance}</b></span><span>Poids <b>${r.poids} g</b></span><span>Niveau <b>${NOMS_NIVEAU[r.niveau]}</b></span></div>
  <div class="bars" style="margin-top:8px"><span>Contrôle</span>${bar(r.controle)}<span>Puissance</span>${bar(r.puissance,"p")}</div></div>
 </article>`).join("")
 // Les suivantes du classement (12 au plus), en liste compacte
 +(list.length>3?`<details class="rk-plus"><summary>Voir les ${Math.min(12,list.length-3)} suivantes</summary><ol start="4">${list.slice(3,15).map(r=>`<li><span><b>${r.marque}</b> ${r.modele}</span><span class="rk-plus-meta">${r.forme} · ${NOMS_NIVEAU[r.niveau]} · ${r.prix} €</span></li>`).join("")}</ol></details>`:"");
}
const bud=document.getElementById("budget"),out=document.getElementById("budget-out");
bud.addEventListener("input",()=>{out.textContent=bud.value+" €";});
document.getElementById("quiz").addEventListener("submit",e=>{e.preventDefault();render();document.getElementById("results").scrollIntoView({behavior:"smooth",block:"nearest"});});
document.getElementById("quiz").addEventListener("change",render);
render();
